/* Public rendering only. Data is generated by the scheduled GitHub Actions collector. */
document.addEventListener('DOMContentLoaded', async () => {
  const root = document.getElementById('tunisia-trend-radar');
  if (!root) return;
  const status = document.getElementById('tn-radar-status');
  const featured = document.getElementById('tn-featured-game');
  const board = document.getElementById('tn-trend-leaderboard');
  const updated = document.getElementById('tn-radar-updated');
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const fmt = value => Number(value || 0).toLocaleString(undefined,{maximumFractionDigits:1});
  try {
    const response = await fetch('/data/tunisian-trends.json?ts='+Date.now(), {cache:'no-store'});
    if (!response.ok) throw new Error('Trend data endpoint unavailable');
    const payload = await response.json();
    const data = payload.current || payload;
    const when = data.updated_at ? new Date(data.updated_at) : null;
    updated.textContent = when && !Number.isNaN(when.getTime()) ? 'LAST CHECK '+when.toLocaleString() : 'WAITING FOR FIRST CHECK';
    if (data.status === 'setup_required') {
      status.textContent = 'SETUP REQUIRED · CREATOR REGISTRY + API CREDENTIALS';
      featured.innerHTML = '<div><p class="pnx-live-kicker"><span></span> TRACKER READY FOR ACTIVATION</p><h4>VERIFY THE LOCAL SCENE.</h4><p>Add Tunisia-confirmed creator channels and API credentials to start collecting historical activity across all three platforms.</p></div><div class="pnx-tn-feature-stat">3 PLATFORMS<small>TWITCH · KICK · YOUTUBE</small></div>';
      board.innerHTML = '<div class="pnx-live-empty">No game is being promoted until real Tunisian creator data has been collected.</div>';
      return;
    }
    const lead = data.featured;
    if (lead) {
      status.textContent = 'LIVE TRACKER · '+fmt(data.sample_count_7d)+' RECENT COLLECTION SAMPLES';
      featured.innerHTML = '<div><p class="pnx-live-kicker"><span></span> CURRENT TUNISIAN SPOTLIGHT</p><h4>'+esc(lead.name)+'</h4><p>'+fmt(lead.unique_channels)+' verified channels · '+esc((lead.platforms||[]).join(' / '))+' · seven-day average '+fmt(lead.avg_viewers)+' viewers across '+fmt(lead.avg_channels)+' live channels per check</p></div><div class="pnx-tn-feature-stat">'+(lead.growth_pct === null ? 'BASELINE' : (lead.growth_pct>0?'+':'')+fmt(lead.growth_pct)+'%')+'<small>7-DAY MOMENTUM</small></div>';
    } else {
      status.textContent = data.status === 'collecting' ? 'BUILDING THE FIRST HISTORICAL BASELINE' : 'NO GAME HAS MET THE MINIMUM THRESHOLD';
      featured.innerHTML = '<div><p class="pnx-live-kicker"><span></span> NO AUTOMATIC SWITCH YET</p><h4>COLLECTING THE SIGNAL.</h4><p>The tracker will wait for enough repeat observations and multiple distinct Tunisian creators before featuring a game.</p></div><div class="pnx-tn-feature-stat">'+fmt(data.sample_count_7d)+'<small>7-DAY CHECKS</small></div>';
    }
    const rows = data.leaderboard || [];
    board.innerHTML = rows.length ? rows.slice(0,8).map((game,index) => '<article class="pnx-tn-rank"><strong>#'+(index+1)+' '+esc(game.name)+'</strong><span>'+fmt(game.unique_channels)+' unique channels · '+esc((game.platforms||[]).join(' / '))+'</span><b>'+fmt(game.avg_viewers)+' avg viewers</b></article>').join('') : '<div class="pnx-live-empty">The ranking will appear once enough historical samples are available.</div>';
  } catch (error) {
    status.textContent = 'TREND DATA TEMPORARILY UNAVAILABLE';
    featured.innerHTML = '<div class="pnx-live-empty">The trend tracker could not load its latest data. Existing Game Hub sections remain available.</div>';
  }
});
